const girdi = (typeof query === 'object' && query !== null) ? query : { firma_adi: query };
const aranan = (girdi.firma_adi || '').toString().trim().toLocaleLowerCase('tr');
if (!aranan) return JSON.stringify({ hata: 'Aranacak firma adı boş olamaz.' });

const tum = $('Tüm Firmaları Getir').all().map(i => i.json);
const n = (s) => (s || '').toString().trim().toLocaleLowerCase('tr');

let eslesen = tum.filter(f => n(f['Firma Adı']) === aranan);
if (eslesen.length === 0) {
  eslesen = tum.filter(f => {
    const ad = n(f['Firma Adı']);
    return ad.includes(aranan) || aranan.includes(ad);
  });
}

if (eslesen.length === 0) {
  return JSON.stringify({
    sonuc: 'bulunamadi',
    mesaj: `'${girdi.firma_adi}' adında (veya yakın) firma bulunamadı.`
  });
}

return JSON.stringify({
  sonuc: 'bulundu',
  bulunan_sayisi: eslesen.length,
  firmalar: eslesen
});

const p = (typeof query === 'object' && query !== null) ? query : {};
const n = (s) => (s || '').toString().trim().toLocaleLowerCase('tr');
const offset = Math.max(0, parseInt(p.offset || '0', 10) || 0);
const limit = 15;

const filtreler = [
  ['firma_adi', 'Firma Adı'],
  ['firma_aciklamasi', 'Firma Açıklaması'],
  ['kanal', 'İletildiği Kanal'],
  ['ana_kategori', 'Ana Kategori'],
  ['alt_kategori', 'Alt Kategori'],
  ['degerlendirme', 'Değerlendirme'],
  ['referans', 'Referans'],
  ['rakipler', 'Rakipler'],
  ['ekip', 'Ekip'],
  ['not_metni', 'Not'],
  ['link', 'Link'],
  ['katilimcilar', 'Katılımcılar']
];

const aktif = filtreler
  .map(([k, alan]) => ({ alan, deger: n(p[k]) }))
  .filter(x => x.deger);

if (aktif.length === 0) {
  return JSON.stringify({ hata: 'En az bir filtre alanı doldurulmalı.' });
}

const tum = $('Tüm Firmaları Getir').all().map(i => i.json);
const eslesen = tum.filter(f => aktif.every(({ alan, deger }) => n(f[alan]).includes(deger)));

const dilim = eslesen.slice(offset, offset + limit).map(f => ({
  'Firma Adı': f['Firma Adı'],
  'Ana Kategori': f['Ana Kategori'],
  'Alt Kategori': f['Alt Kategori'],
  'Değerlendirme': f['Değerlendirme'],
  'İletildiği Kanal': f['İletildiği Kanal'],
  'Referans': f['Referans'],
  'Ekip': f['Ekip'],
  'Firma Açıklaması': f['Firma Açıklaması']
}));

return JSON.stringify({
  uygulanan_filtreler: aktif.map(a => ({ alan: a.alan, deger: a.deger })),
  toplam_eslesen_sayisi: eslesen.length,
  offset,
  gosterilen_kayit_sayisi: dilim.length,
  daha_var: offset + dilim.length < eslesen.length,
  kayitlar: dilim
});

const p = (typeof query === 'object' && query !== null) ? query : {};
const istenen = (p.alan || '').toString().trim().toLocaleLowerCase('tr');
const tum = $('Tüm Firmaları Getir').all().map(i => i.json);

const alanMap = {
  firma_adi: 'Firma Adı',
  firma_aciklamasi: 'Firma Açıklaması',
  kanal: 'İletildiği Kanal',
  ana_kategori: 'Ana Kategori',
  alt_kategori: 'Alt Kategori',
  degerlendirme: 'Değerlendirme',
  referans: 'Referans',
  rakipler: 'Rakipler',
  ekip: 'Ekip',
  not_metni: 'Not',
  link: 'Link',
  katilimcilar: 'Katılımcılar'
};

function grupla(alan) {
  const sonuc = {};
  for (const f of tum) {
    const ham = f[alan];
    const deger = (ham === null || ham === undefined || String(ham).trim() === '') ? 'Belirtilmemiş' : String(ham);
    sonuc[deger] = (sonuc[deger] || 0) + 1;
  }
  return Object.entries(sonuc)
    .sort((a, b) => b[1] - a[1])
    .map(([deger, adet]) => ({ deger, adet, yuzde: tum.length ? Math.round((adet / tum.length) * 1000) / 10 : 0 }));
}

const cevap = { toplam_firma_sayisi: tum.length };

if (alanMap[istenen]) {
  cevap.kirilim_alani = alanMap[istenen];
  cevap.dagilim = grupla(alanMap[istenen]);
} else {
  cevap.ana_kategori_dagilimi = grupla('Ana Kategori');
  cevap.alt_kategori_dagilimi = grupla('Alt Kategori');
  cevap.degerlendirme_dagilimi = grupla('Değerlendirme');
  cevap.kanal_dagilimi = grupla('İletildiği Kanal');
  cevap.referans_dagilimi = grupla('Referans');
}

return JSON.stringify(cevap);

const p = (typeof query === 'object' && query !== null) ? query : {};
const n = (s) => (s || '').toString().trim().toLocaleLowerCase('tr');
const hedefDeg = n(p.degerlendirme);
const hedefAna = n(p.ana_kategori);
const offset = Math.max(0, parseInt(p.offset || '0', 10) || 0);
const tum = $('Tüm Firmaları Getir').all().map(i => i.json);

function grupla(alan) {
  const sonuc = {};
  for (const f of tum) {
    const ham = f[alan];
    const deger = (ham === null || ham === undefined || String(ham).trim() === '') ? 'Belirtilmemiş' : String(ham);
    sonuc[deger] = (sonuc[deger] || 0) + 1;
  }
  return Object.entries(sonuc)
    .sort((a, b) => b[1] - a[1])
    .map(([deger, adet]) => ({ deger, adet, yuzde: tum.length ? Math.round((adet / tum.length) * 1000) / 10 : 0 }));
}

const capraz = {};
for (const f of tum) {
  const kat = (f['Ana Kategori'] && String(f['Ana Kategori']).trim()) || 'Belirtilmemiş';
  const deg = (f['Değerlendirme'] && String(f['Değerlendirme']).trim()) || 'Belirtilmemiş';
  if (!capraz[kat]) capraz[kat] = {};
  capraz[kat][deg] = (capraz[kat][deg] || 0) + 1;
}

const cevap = {
  toplam_firma_sayisi: tum.length,
  degerlendirme_dagilimi: grupla('Değerlendirme'),
  ana_kategori_x_degerlendirme: capraz
};

let liste = tum;
if (hedefDeg) liste = liste.filter(f => n(f['Değerlendirme']).includes(hedefDeg));
if (hedefAna) liste = liste.filter(f => n(f['Ana Kategori']).includes(hedefAna));

if (hedefDeg || hedefAna) {
  const dilim = liste.slice(offset, offset + 15).map(f => ({
    'Firma Adı': f['Firma Adı'],
    'Ana Kategori': f['Ana Kategori'],
    'Alt Kategori': f['Alt Kategori'],
    'Değerlendirme': f['Değerlendirme'],
    'İletildiği Kanal': f['İletildiği Kanal'],
    'Referans': f['Referans']
  }));
  cevap.filtreli_toplam = liste.length;
  cevap.offset = offset;
  cevap.gosterilen_kayit_sayisi = dilim.length;
  cevap.daha_var = offset + dilim.length < liste.length;
  cevap.kayitlar = dilim;
}

return JSON.stringify(cevap);

const p = (typeof query === 'object' && query !== null) ? query : { arama_metni: query };
const n = (s) => (s || '').toString().trim().toLocaleLowerCase('tr');
const arama = n(p.arama_metni);
const offset = Math.max(0, parseInt(p.offset || '0', 10) || 0);
if (!arama) return JSON.stringify({ hata: 'Arama metni boş olamaz.' });

const kelimeler = arama.split(/\s+/).filter(Boolean);
const tum = $('Tüm Firmaları Getir').all().map(i => i.json);

const eslesen = tum.filter(f => {
  const metin = n([f['Firma Adı'], f['Firma Açıklaması'], f['Not'], f['Ana Kategori'], f['Alt Kategori'], f['Referans']].filter(Boolean).join(' '));
  return kelimeler.every(k => metin.includes(k)) || kelimeler.some(k => metin.includes(k));
});

const dilim = eslesen.slice(offset, offset + 15).map(f => ({
  'Firma Adı': f['Firma Adı'],
  'Ana Kategori': f['Ana Kategori'],
  'Alt Kategori': f['Alt Kategori'],
  'Değerlendirme': f['Değerlendirme'],
  'Firma Açıklaması': f['Firma Açıklaması'],
  'Not': f['Not']
}));

return JSON.stringify({
  arama_metni: p.arama_metni,
  toplam_eslesen_sayisi: eslesen.length,
  offset,
  gosterilen_kayit_sayisi: dilim.length,
  daha_var: offset + dilim.length < eslesen.length,
  kayitlar: dilim
});

const p = (typeof query === 'object' && query !== null) ? query : {};
const alanMap = {
  gorusme_tarihi: 'Görüşme Tarihi',
  yol_haritasi_giris_tarihi: 'Yol Haritası Giriş Tarihi'
};
const alan = alanMap[(p.tarih_alani || '').toString().trim().toLocaleLowerCase('tr')];
if (!alan) {
  return JSON.stringify({ hata: "tarih_alani 'gorusme_tarihi' veya 'yol_haritasi_giris_tarihi' olmalı." });
}

function tarihiCoz(deger) {
  if (!deger) return null;
  const d = new Date(deger);
  return isNaN(d.getTime()) ? null : d;
}

const yil = p.yil ? parseInt(p.yil, 10) : null;
const baslangic = tarihiCoz(p.baslangic_tarihi);
const bitis = tarihiCoz(p.bitis_tarihi);
const offset = Math.max(0, parseInt(p.offset || '0', 10) || 0);

if (!yil && !baslangic && !bitis) {
  return JSON.stringify({ hata: 'En az yil, baslangic_tarihi veya bitis_tarihi gerekli.' });
}

const tum = $('Tüm Firmaları Getir').all().map(i => i.json);
const eslesen = tum.filter(f => {
  const tarih = tarihiCoz(f[alan]);
  if (!tarih) return false;
  if (yil && tarih.getFullYear() !== yil) return false;
  if (baslangic && tarih < baslangic) return false;
  if (bitis && tarih > bitis) return false;
  return true;
});

const dilim = eslesen.slice(offset, offset + 15).map(f => ({
  'Firma Adı': f['Firma Adı'],
  [alan]: f[alan],
  'Ana Kategori': f['Ana Kategori'],
  'Değerlendirme': f['Değerlendirme'],
  'Katılımcılar': f['Katılımcılar']
}));

return JSON.stringify({
  tarih_alani: alan,
  toplam_eslesen_sayisi: eslesen.length,
  offset,
  gosterilen_kayit_sayisi: dilim.length,
  daha_var: offset + dilim.length < eslesen.length,
  kayitlar: dilim
});

